insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('d-four-checkouts-on-measured-disk-s714','decision','Four checkouts on measured disk','S714 conductor: four worker checkouts ran at once, at about 2 GB each against 55 GB free, over the three-checkout ceiling S653 set when a checkout took 4.4 to 4.7 GB. The ceiling is now the measured disk: git worktree list and df -h before each spawn, since a light clone''s checkout is about 2 GB.',array['conductor','workers','disk'],'proposed','docs/reference/conductor_mode.md (Start, step 5); docs/session_716_handoff.md','SkyFulmar (S714), the conductor',null,'SkyFulmar (S714)',date '2026-11-23'),
('d-apply-before-reach-fix-s714','decision','Apply first, fix forward when the majors miss the write','S714 conductor: when a second reader''s majors touch neither the plan''s rows, its SQL nor its undo, the apply runs first and the fixes follow on the branch. City College of San Francisco (#3714: the reach count and the test) and East Los Angeles (#3716: the electives scope, main''s merge) went live by migrates 45176130201 and 45186909162 before their merges.',array['conductor','guarded-update','review','program-requirements'],'proposed','#3714; #3716','SkyFulmar (S714), the conductor',null,'SkyFulmar (S714)',date '2026-11-23'),
('d-optparts-holds-05934-claim-check-s714','decision','Santa Barbara City 05934 held on its claim check','S714 conductor: the option_parts follow-up (#3719) went from 10 rows to 9 because Santa Barbara City 05934''s claim check on today''s capture finds 31 of its option''s 33 listed courses (ENVS 112 and ENVS 115 missing). A read settles them; migrate 45188487600 applied the other 9.',array['program-requirements','option-parts','claim-check','santa-barbara-city'],'proposed','#3719; kb/receipts/program_requirement_records_piles_optparts_2026-11-23_s714o.json','SkyFulmar (S714), the conductor',null,'SkyFulmar (S714)',date '2026-11-23'),
('d-elective-fill-rereads-held-s714','decision','The nine Los Rios rescored records held, never reread','S714 conductor: the nine records the Los Rios reconciles newly passed (Sacramento City 04656, 07350, 21418; Cosumnes River 04602, 04614, 33542; Folsom Lake 15368, 39574, 42612) went back to main''s filings, never reread. A Sonnet reader found 8 pass only through the program-level electives fill while their notes say the table was cut off. They wait for the fill''s fix.',array['program-requirements','los-rios','reconcile','held'],'proposed','#3715 597cfd85','SkyFulmar (S714), the conductor',null,'SkyFulmar (S714)',date '2026-11-23'),
('d-fullerton-rides-3719-s714','decision','Fullerton''s 11 ride #3719','S714 conductor: Fullerton''s 11 records (migrate 45191999745) ride #3719 with the option_parts 9, one PR for two applied branches while the open PRs sat at the cap. Its PE 248 F renumber was dropped before the merge: the state file holds two PE 248 courses and the printed form matches the other one; it moved none of the 11 but rewrote 18166''s score.',array['conductor','merge-order','fullerton','program-requirements'],'proposed','#3719','SkyFulmar (S714), the conductor',null,'SkyFulmar (S714)',date '2026-11-23'),
('d-sonnet-reader-for-scoped-plans-s714','decision','Sonnet second readers on scoped plans','S714 conductor: a plan whose shared code a second reader already reviewed, or that changes no shared code, gets a Sonnet second reader: the option_parts follow-up, Fullerton''s plan and the nine Los Rios rescored records. A plan that changes shared reader or scorer code keeps an Opus reader before its apply or dispatch (the S652 rule).',array['conductor','review','models'],'proposed','docs/reference/conductor_mode.md S714','SkyFulmar (S714), the conductor',null,'SkyFulmar (S714)',date '2026-11-23'),
('d-cobix-watcher-stopped-on-sam-word-s714','decision','The COBIx watcher stopped on Sam''s word','S714 conductor, on Sam''s word to S712 at 01:53Z 2026-11-23, recorded in handoff 715: "No need for the Cobix check ins for now". The run stopped its COBIx watcher at 12:58Z, when it read the handoff, and read each PR''s whole thread before its merge instead. A watcher starts again only when Sam asks.',array['conductor','cobix','sam-word'],'proposed','docs/session_715_handoff.md; docs/session_716_handoff.md','SkyFulmar (S714), the conductor',null,'SkyFulmar (S714)',date '2026-11-23'),
('p-one-pending-run-per-branch-s714','pitfall','One pending run per branch','S714: the college workflow''s concurrency group holds one running and one pending run per branch, and a newer pending run cancels the older one. Of three Los Rios reads dispatched at once, Cosumnes River''s pending run 45181979022 was canceled four seconds after Folsom Lake''s dispatch, before anything was paid. Dispatch one at a time (S655; p-read-dispatches-share-group-s687).',array['workflows','dispatch','concurrency','conductor'],'proposed','docs/reference/conductor_mode.md S714; run 45181979022','SkyFulmar (S714), the conductor',null,'SkyFulmar (S714)',date '2026-11-23'),
('p-harness-keeps-worker-in-its-worktree-s714','pitfall','A worker cannot open a second worktree','S714: the harness keeps a worker inside its own worktree, so piles could not open a second checkout for East Los Angeles while #3714''s reader needed its first one at the PR head. A fresh worker, piles2, took East Los Angeles in its own worktree. Start a fresh worker for each new branch.',array['workers','worktrees','conductor'],'proposed','docs/reference/conductor_mode.md (Start, step 5)','SkyFulmar (S714), the conductor',null,'SkyFulmar (S714)',date '2026-11-23'),
('p-load-skips-places-none-s714','procedure','A load inserts only records with no live row','S714: step=load on the college workflow inserts only records with no live row and skips any that places none of its courses. None of the 37 Los Rios records from three paid reads had a live row, so each went live by load (45198701869, 45199218981, 45199758327) with no guarded plan.',array['program-requirements','load','workflows'],'proposed','kb/receipts/program_requirement_records_college_sacramento_city_45198701869.json; #3715','SkyFulmar (S714), the conductor',null,'SkyFulmar (S714)',date '2026-11-23'),
('f-elective-fill-passes-cut-off-windows-s714','risk','The program-level fill passes cut-off windows','S714: main''s program-level fill in kb/_program_requirements_score.py (about line 1478: electives_fill_degree, no degree total, hi <= stated) passes a record whose window was cut off whenever elective appears in its text; 8 Los Rios records showed it. S655''s guard reads six colleges and a note pattern matching none of the 8. Measure it statewide before the next reconcile anywhere.',array['program-requirements','scorer','reconcile','false-pass'],'proposed','docs/kb-notes/methodology-a-fill-must-check-what-it-fills.md; #3715','SkyFulmar (S714), the conductor',null,'SkyFulmar (S714)',date '2026-11-23'),
('f-rescore-drops-ge-units-not-read-gaps-s714','fact','The reconcile rescore drops ge_units_not_read gaps','S714: the three Los Rios reconciles (45184748331, 45185759855, 45187906040) rescored records outside their pinned programs and dropped the named ge_units_not_read gaps S703''s apply wrote on 16 of them. rios put back the 49 rescored records whose pass state did not move, and Cosumnes River 07319. A reader bug: fix it, or put records back, before the next reconcile.',array['program-requirements','reconcile','named-gaps','follow-up'],'proposed','#3715 2db01aea','SkyFulmar (S714), the conductor',null,'SkyFulmar (S714)',date '2026-11-23'),
('f-american-river-hand-filed-sha-mismatch-s714','fact','American River''s hand-filed catalog no longer matches','S714: American River''s host now serves a catalog file whose sha256 differs from the hand-filed record the page read pins, so its 5 programs on the reader-page lever are blocked while the other three Los Rios colleges read. A checked filing of the file the host serves now clears it.',array['program-requirements','american-river','hand-filed-catalogs','blocked'],'proposed','#3715','SkyFulmar (S714), the conductor',null,'SkyFulmar (S714)',date '2026-11-23'),
('f-cobix-minors-s714','fact','For COBIx: the second readers'' minors from S714','S714, for COBIx: the same-figure guard reads true parts that print one figure as alternatives; East Los Angeles''s bound is unmeasured on capture text (41097 likely; 36345, 37924, 43632, 45935 possible), so a free reconcile measures it; the database rows lack notes and missing_explained, so a receipt-only rescore fails coverage on 4 option_parts rows; Fullerton''s CRTV 196 F prints 0.5-3 units.',array['program-requirements','cobix','follow-up'],'proposed','#3714; #3716; #3719','SkyFulmar (S714), the conductor',null,'SkyFulmar (S714)',date '2026-11-23'),
('m-collection-s714','milestone','S714''s collection: 80 records live','S714 (2026-11-23): 80 program records live, 77 passing, $4.13 of paid reads: City College of San Francisco 8 (#3714); East Los Angeles 15, 45602 a named gap (#3716); option_parts 9 at six colleges and Fullerton 11 (#3719); Los Rios 37 loaded from three paid reads (#3715: Sacramento City 18, Cosumnes River 16, Folsom Lake 3), 7 named gaps filed. College of the Sequoias'' 14 were pending.',array['program-requirements','collection','los-rios'],'proposed','#3714; #3716; #3719; #3715','SkyFulmar (S714), the conductor',null,'SkyFulmar (S714)',date '2026-11-23')
insert into public.cpl_memory_log (memory_id, actor, action, note, after)
